export function getTranslatedDailyTitle(title: string, language: string): string {
  if (language === "en") return title
  return dailyTitleTranslations[title]?.[language] || title
}

export function getTranslatedDailyBody(body: string, language: string): string {
  if (language === "en") return body
  return dailyBodyTranslations[body]?.[language] || body
}